#' Example simulated PK concentration data
#'
#' A small synthetic dataset from a one-compartment IV bolus model with
#' two dose levels, used in function examples and the package vignette.
#' Generated by \code{data-raw/pmxvpc_example_data.R}.
#'
#' @format A data frame with 1120 rows and 6 variables:
#' \describe{
#'   \item{ID}{Subject identifier (8 subjects).}
#'   \item{REP}{Simulation replicate (20 replicates).}
#'   \item{TIME}{Nominal sampling time.}
#'   \item{DOSE}{Dose level (100 or 300).}
#'   \item{DV}{Simulated concentration.}
#'   \item{PRED}{Population-only (typical) prediction -- identical
#'     across replicates for a given \code{ID}/\code{TIME}.}
#' }
#' @seealso \code{\link{pmxvpc_obs_example}}
"pmxvpc_sim_example"

#' Example observed PK concentration data
#'
#' The observed counterpart to \code{\link{pmxvpc_sim_example}}: one
#' realization per subject from the same model and dose levels.
#' Generated by \code{data-raw/pmxvpc_example_data.R}.
#'
#' @format A data frame with 56 rows and 5 variables:
#' \describe{
#'   \item{ID}{Subject identifier (8 subjects).}
#'   \item{TIME}{Nominal sampling time.}
#'   \item{DOSE}{Dose level (100 or 300).}
#'   \item{DV}{Observed concentration.}
#'   \item{PRED}{Population-only (typical) prediction, matching
#'     \code{\link{pmxvpc_sim_example}}'s \code{PRED} at the same
#'     \code{DOSE}/\code{TIME}.}
#' }
#' @seealso \code{\link{pmxvpc_sim_example}}
"pmxvpc_obs_example"
